import sys
import copy
sys.path.insert(0, r'token-master-plugin\skills\token-master')
from brainspace.jev import is_high_confidence, ValidationError
for kind, field in [('choice', 'confidence'), ('score', 'confidence'), ('noul', 'noul')]:
    for value in [0, 0.1, 0.5, 0.8, 0.9, 1]:
        answer = {'type': kind, field: value}
        original = copy.deepcopy(answer)
        confidence = max(value, 1 - value) if kind == 'noul' else value
        assert is_high_confidence(answer) == (confidence >= 0.8)
        for threshold in [0, 0.5, 0.8, 1]:
            assert is_high_confidence(answer, threshold) == (confidence >= threshold)
        assert answer == original
    for value in [None, True, '0.9', -0.1, 1.1, float('nan'), float('inf'), -float('inf'), 10**400]:
        try:
            is_high_confidence({'type': kind, field: value})
        except ValidationError as error:
            assert str(error) == 'invalid_response'
        else:
            raise AssertionError('malformed answer accepted')
for threshold in [None, True, False, '0.8', -0.1, 1.1, float('nan'), float('inf'), -float('inf'), 10**400]:
    try:
        is_high_confidence({'type': 'noul', 'noul': 0.9}, threshold)
    except ValidationError as error:
        assert str(error) == 'invalid_threshold'
    else:
        raise AssertionError('invalid threshold accepted')
for answer in [None, [], {}, {'type': 'other'}, {'type': []}, {'type': 'choice'}, {'type': 'score'}, {'type': 'noul'}]:
    try:
        is_high_confidence(answer)
    except ValidationError as error:
        assert str(error) == 'invalid_response'
    else:
        raise AssertionError('malformed answer accepted')
print('Confidence checks passed')
